create extension if not exists postgis;
create table stops (id text primary key, city text not null, name text not null, latitude double precision not null, longitude double precision not null, stop_type text not null check (stop_type in ('bus_stop','bus_park','keke_stop','okada_stop','taxi_stop','junction','landmark')), landmark text, description text, confidence numeric check (confidence between 0 and 1), source text not null, last_updated timestamptz default now(), location geography(point,4326));
create table routes (id text primary key, city text not null, name text not null, vehicle_type text not null check (vehicle_type in ('bus','keke','okada','taxi')), direction text not null, description text, estimated_duration integer, fare_min integer check (fare_min >= 0), fare_max integer check (fare_max >= fare_min), reliability numeric, confidence numeric, source text not null, last_updated timestamptz default now());
create table route_stops (id bigint generated always as identity primary key, route_id text references routes(id) on delete cascade, stop_id text references stops(id), sequence integer not null, boarding_allowed boolean default true, alighting_allowed boolean default true, unique(route_id,sequence));
create table walking_edges (from_stop text references stops(id), to_stop text references stops(id), distance integer not null check(distance >= 0), duration integer not null check(duration >= 0), primary key(from_stop,to_stop));
create table fares (id bigint generated always as identity primary key, route_id text references routes(id), stop_from text references stops(id), stop_to text references stops(id), fare_min integer not null, fare_max integer not null, source text not null, confidence numeric, effective_date date);
create table user_reports (id uuid primary key default gen_random_uuid(), report_type text not null check(report_type in ('wrong_fare','route_changed','stop_missing','stop_moved','route_unavailable','unsafe_area','other')), route_id text references routes(id), stop_id text references stops(id), latitude double precision, longitude double precision, description text, status text default 'pending', created_at timestamptz default now());
